"""Catalog coverage, resource integrity and original musical configurations."""
import json
import shutil

import pytest

from vocal_app.core.catalog import load_catalog


@pytest.fixture(scope="module")
def catalog():
    return load_catalog(verify_hashes=True)


@pytest.mark.parametrize("exercise_id", range(1, 40))
def test_every_principal_matches_original_javascript(catalog, exercise_id):
    # These fixtures are buildTrainingConfig(exercise) results executed in the
    # original JS implementation, not generated by the Python implementation.
    originals = json.loads((catalog.assets_dir / "principal-configs.json").read_text(encoding="utf-8"))
    original = next(config for config in originals if config["exerciseId"] == exercise_id)
    exercise = catalog.by_id[exercise_id]
    assert exercise.name == original["exerciseName"]
    assert exercise.objective == original["objective"]
    assert exercise.mode == original["mode"]
    if exercise_id == 27:
        # Explicit desktop correction: the source fixture only holds one motif.
        expected = tuple(original["vocalNotes"] + [None]) * 4 + tuple(original["vocalNotes"])
        assert exercise.vocal_notes == exercise.guide_notes == expected
    else:
        assert exercise.vocal_notes == tuple(original["vocalNotes"])
        assert exercise.guide_notes == tuple(original["guideNotes"])
    assert exercise.bpm == original["bpm"]
    assert exercise.subdivision == original["subdivision"]
    assert exercise.breathing_seconds == original["breathingDurationSec"]
    assert catalog.asset_path(exercise.audio).is_file()
    if exercise.image:
        assert catalog.asset_path(exercise.image).is_file()


@pytest.mark.parametrize("session,expected", [
    ("A", (1, 2, 13, 32, 34, 36, 38)),
    ("B", (1, 3, 13, 33, 35, 37, 39)),
    ("C", (1, 2, 5, 6, 7, 8, 10)),
    ("D", (1, 13, 4, 9, 11, 12, 14)),
    ("E", (1, 2, 13, 14, 15, 16, 17, 18, 19, 20)),
    ("F", (1, 3, 13, 21, 22, 23)),
    ("G", (1, 13, 24, 25, 26, 21, 22)),
    ("H", (1, 2, 13, 27, 28, 29, 30, 31)),
])
def test_original_session_order(catalog, session, expected):
    assert catalog.sessions[session] == expected
    assert catalog.session_focus[session]


def test_complete_catalog_and_resource_counts(catalog):
    assert len(catalog.exercises) == 39
    assert set().union(*map(set, catalog.sessions.values())) == set(range(1, 40))
    assert len(list(catalog.assets_dir.rglob("*.mp3"))) == 39
    assert len(list(catalog.assets_dir.rglob("*.png"))) == 36
    assert catalog.source_revision == "41a5ec8dc9c6574cb025e6a4b3389d4a9c0a1009"
    assert not list(catalog.assets_dir.rglob("*.htm*"))


def test_historical_spelling_preserved(catalog):
    assert catalog.by_id[16].name == "Chewy Chrrey"
    assert catalog.by_id[16].audio == "sample_vocal/Chewy Cherry.mp3"
    assert catalog.by_id[27].audio == "sample_vocal/Thee-Note Run.mp3"
    assert catalog.by_id[27].image == "tablaturas/Three-Note run.png"
    assert catalog.by_id[23].audio == "sample_vocal/bouncing Eh.mp3"
    assert catalog.by_id[33].image == "tablaturas/Minor Sacale Ascending.png"
    assert catalog.by_id[39].image == "tablaturas/Minor Sale Desc. Intervals.png"


def test_breathing_is_not_pitch(catalog):
    for exercise_id in (1, 2, 3):
        exercise = catalog.by_id[exercise_id]
        assert exercise.mode == "breathing"
        assert exercise.image is None
        assert exercise.notes == "qualquer"
        assert exercise.vocal_notes == exercise.guide_notes == ()
        assert exercise.breathing_seconds == 30


def test_assets_are_independent_of_working_directory(catalog, monkeypatch, tmp_path):
    monkeypatch.chdir(tmp_path)
    assert load_catalog().assets_dir == catalog.assets_dir


def test_no_path_escape(catalog):
    with pytest.raises(ValueError, match="fora da pasta"):
        catalog.asset_path("../private-recording.wav")


def test_missing_resource_is_actionable(catalog, tmp_path):
    for name in ("catalog.json", "manifest.json"):
        shutil.copyfile(catalog.assets_dir / name, tmp_path / name)
    with pytest.raises(FileNotFoundError, match="Recurso do exercício 1 ausente"):
        load_catalog(tmp_path)


def test_manifest_mismatch_is_rejected(catalog, tmp_path):
    shutil.copyfile(catalog.assets_dir / "catalog.json", tmp_path / "catalog.json")
    manifest = json.loads((catalog.assets_dir / "manifest.json").read_text(encoding="utf-8"))
    manifest["resources"][0]["path"] = "sample_vocal/wrong.mp3"
    (tmp_path / "manifest.json").write_text(json.dumps(manifest), encoding="utf-8")
    with pytest.raises(ValueError, match="Manifesto não corresponde"):
        load_catalog(tmp_path)
